mapper.select:
SELECT id, order_no, customer_name, customer_phone, customer_address, product_type, product_spec, product_num, unit_price, total_price, remark, status, create_time, update_time FROM sys_order
AND order_no = #{orderNo}
AND customer_name like concat('%', #{customerName}, '%')
AND status = #{status}
ORDER BY create_time DESC
